ON CONFLICT (account_id) DO UPDATE SET account_name = EXCLUDED.account_name, account_code = EXCLUDED.account_code;

ON CONFLICT (program_id) DO UPDATE SET program_name = EXCLUDED.program_name;

ON CONFLICT (allocation_id) DO NOTHING;

ON CONFLICT (commitment_id) DO NOTHING;

ON CONFLICT (invoice_id) DO NOTHING;

ON CONFLICT (payment_id) DO NOTHING;

ON CONFLICT (journal_id) DO NOTHING;

ON CONFLICT (tco_id) DO NOTHING;

ON CONFLICT (line_id) DO NOTHING;
